   // Step 1: Group cities by state ID
const stateCityMap = {};
let states = new Set(); // Use Set to automatically handle duplicates

jsonData.forEach(({ state, city }) => {
  if (!stateCityMap[state]) {
    stateCityMap[state] = [];
  }
  stateCityMap[state].push(city);
  states.add(state);
});

// Step 2: Populate state dropdown
const stateSelect = document.getElementById("stateSelect");
const citySelect = document.getElementById("citySelect");
states = Array.from(states).sort();
for (const state of states) {
  const option = new Option(state, state); // cleaner option creation
  stateSelect.add(option);
}

// Step 3: Update city dropdown on state change
// Step 3: Update city dropdown on state change
stateSelect.addEventListener("change", () => {
  citySelect.innerHTML = '<option value="">Select City</option>';
  const selectedState = stateSelect.value;
  
  if (selectedState && stateCityMap[selectedState]) {
    const sortedCities = stateCityMap[selectedState].sort();
    for (const city of sortedCities) {
      const option = new Option(city, city);
      citySelect.add(option);
    }
  }
});